     1	import {shouldContinueToolLoop, accumulateUsage} from './orchestratorHelpers.js';
     2	import type {ToolRegistry} from './tools/registry.js';
     3	import type {ToolCall, UsageMetadata} from '../types/ai.js';
     4	
     5	// All three conditions matter; dropping the registry check spins the tool loop.
     6	
     7	const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
     8	const REGISTRY = {} as ToolRegistry;
     9	
    10	describe('shouldContinueToolLoop', () => {
    11	  it('continues when the model requested a tool and a registry can run it', () => {
    12	    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
    13	  });
    14	
    15	  it('stops when no registry is configured, whatever the model asked for', () => {
    16	    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
    17	  });
    18	
    19	  it('stops when the model named no tool', () => {
    20	    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
    21	  });
    22	
    23	  it('stops when the model finished for a reason other than tool use', () => {
    24	    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
    25	  });
    26	});
    27	
    28	describe('accumulateUsage', () => {
    29	  it('sums token fields when both operands are defined', () => {
    30	    const a: UsageMetadata = {inputTokens: 10, outputTokens: 4, totalTokens: 14};
    31	    const b: UsageMetadata = {inputTokens: 25, outputTokens: 8, totalTokens: 33};
    32	    expect(accumulateUsage(a, b)).toEqual({inputTokens: 35, outputTokens: 12, totalTokens: 47});
    33	  });
    34	
    35	  it('returns the defined side when one operand is undefined', () => {
    36	    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    37	    expect(accumulateUsage(undefined, usage)).toEqual(usage);
    38	    expect(accumulateUsage(usage, undefined)).toEqual(usage);
    39	  });
    40	
    41	  it('returns undefined when both operands are undefined', () => {
    42	    expect(accumulateUsage(undefined, undefined)).toBeUndefined();
    43	  });
    44	});
specs/hal-engine-chat-routes/spec.md:17:- The chat is looked up second. An id with no chat is `404 Chat not found` ([validated by: answers 404 for a chat that does not exist](../../src/transport/routes/chats.test.ts#L77)).
specs/hal-engine-chat-routes/spec.md:18:- Ownership is checked third. A caller who is not the recorded owner gets `403 Forbidden` and no part of the chat ([validated by: refuses a different user with 403 and no chat content](../../src/transport/routes/chats.test.ts#L68)).
specs/hal-engine-chat-routes/spec.md:19:- A caller who is not the owner still sees `404` for an id that does not exist, so ownership never becomes an oracle for which ids are real ([validated by: answers 404 before 403, so a wrong owner cannot probe which ids exist](../../src/transport/routes/chats.test.ts#L85)).
specs/hal-engine-chat-routes/spec.md:20:- Owner ids are compared strictly, so numeric `1` and string `"1"` are different users rather than the same one ([validated by: compares owner ids strictly, so numeric 1 and string "1" are different users](../../src/transport/routes/chats.test.ts#L103)).
specs/hal-engine-chat-routes/spec.md:26:- Creating a chat is refused `401 Unauthorized` ([validated by: refuses to create a chat](../../src/transport/routes/chats.test.ts#L214)).
